import json
from urllib.parse import quote, urljoin

from bs4 import BeautifulSoup

from SessionManager import verification_activity_get
from WebViewClient import web_get
from log import log

# 章节正文最多翻多少页，防止异常链接导致死循环
_MAX_PAGES = 10

# 命中这些特征说明触发了人机验证，需要交给前台 WebView
_VERIFY_MARKERS = (
    "challenges.cloudflare.com",
    "此验证用于防止机器人自动化访问",
    "Just a moment",
)


def _is_verify(html):
    return any(marker in html for marker in _VERIFY_MARKERS)


def _fetch(url):
    """直接走 WebView；后台 WebView 被拦截时转前台人工验证，返回 {url, html} 的 JSON"""
    def parse(result):
        result = json.loads(result)
        result["html"] = result.get("html", "")
        if _is_verify(result["html"]):
            raise Exception("人机验证")
        return result

    try:
        return json.dumps(parse(web_get(url)), ensure_ascii=False)
    except Exception as e:
        log(f"顶点小说 web_get 失败，转人工验证: {e}")
        return json.dumps(parse(verification_activity_get(url)), ensure_ascii=False)


def getSiteUrl():
    return "https://m.terry-haass.com"


def search(query):
    def parseResult(result):
        result = json.loads(result)
        soup = BeautifulSoup(result.get("html"), "html.parser")

        books = []
        for bookEl in soup.select(".sone"):
            links = bookEl.select("a")
            if len(links) < 2:
                continue
            href = links[0].get("href") or ""
            bookUrl = f"https://m.terry-haass.com/{href.split('/')[1]}/"
            books.append({
                "bookTitle": links[0].text.strip(),
                "bookUrl": urljoin(url, bookUrl),
                "bookAuthor": links[1].text.strip(),
            })

        return books

    url = ("https://m.terry-haass.com/modules/article/search.php?"
           f"searchkey={quote(query)}&Submit.x=20&Submit.y=16")
    return parseResult(_fetch(url))


def getDetails(url):
    def parseBookInfo(result):
        result = json.loads(result)
        soup = BeautifulSoup(result.get("html"), "html.parser")
        return {
            "url": url,
            "title": soup.select_one("meta[property='og:novel:book_name']").get("content"),
            "author": soup.select_one("meta[property='og:novel:author']").get("content"),
            "intro": soup.select_one("meta[property='og:description']").get("content"),
            "cover": soup.select_one("meta[property='og:image']").get("content"),
        }

    def parseChapterList(result):
        result = json.loads(result)
        soup = BeautifulSoup(result.get("html"), "html.parser")

        chapterList = []
        for chapter_el in soup.select(".infoad"):
            title = chapter_el.text.split("&nbsp;")[0].strip()
            href = chapter_el.get("href")
            if not title or not href:
                continue
            chapterList.append({
                "title": title,
                "url": urljoin(url, href),
            })
        return chapterList

    url = url.replace("://www.", "://m.")
    book = parseBookInfo(_fetch(url))
    book["chapterList"] = parseChapterList(_fetch(url + "/index.html"))

    return book


def _extract_content(soup, url, visited, depth):
    if url in visited or depth >= _MAX_PAGES:
        return ""
    visited.add(url)

    parts = []
    for p in soup.select("#novelcontent > p"):
        text = p.get_text(strip=True)
        if not text:
            continue
        classes = " ".join(p.get("class") or [])
        if "chapternext" in classes:
            continue
        # 过滤导航和“退出阅读模式”提示
        if any(word in text for word in ("下一页", "上一页", "转码失败", "阅读模式")):
            continue
        parts.append(text)

    html = "<p>" + "</p><p>".join(parts) + "</p>" if parts else ""

    # 只认同一章节的分页（xxx_2.html），不要外站广告里的“下一页”
    base = url[:-5] if url.endswith(".html") else url
    next_url = ""
    for a in soup.select("a[href]"):
        full = urljoin(url, a.get("href"))
        if full.startswith(base + "_") and full != url:
            next_url = full
            break

    if next_url:
        data = json.loads(_fetch(next_url))
        next_soup = BeautifulSoup(data.get("html"), "html.parser")
        html += _extract_content(next_soup, next_url, visited, depth + 1)

    return html


def getChapterContent(url):
    data = json.loads(_fetch(url))
    soup = BeautifulSoup(data.get("html"), "html.parser")
    return _extract_content(soup, data.get("url") or url, set(), 0)

import json
import re
from urllib.parse import urljoin, quote

from bs4 import BeautifulSoup, NavigableString
from log import log

from SessionManager import verification_activity_get
from WebViewClient import web_get


# 站点直连会触发 Cloudflare 人机验证，直接走 WebView
_VERIFY_MARKERS = (
    "challenges.cloudflare.com",
    "此验证用于防止机器人自动化访问",
    "Just a moment",
)


def _is_verify(html):
    return any(marker in html for marker in _VERIFY_MARKERS)


def _fetch(url):
    """直接走 WebView；后台 WebView 被拦截时转前台人工验证"""
    def parse(result):
        result = json.loads(result)
        html = result.get("html", "")
        if _is_verify(html):
            raise Exception("人机验证")
        return html

    try:
        return parse(web_get(url))
    except Exception as e:
        log(f"web_get 失败，转人工验证: {e}")
        return parse(verification_activity_get(url))


def getSiteUrl():
    return "https://cn.zhys.tw"


def search(query):
    url = urljoin(getSiteUrl(), f"/search?q={quote(query)}")
    html = _fetch(url)
    soup = BeautifulSoup(html, "html.parser")
    books = []

    # 搜索结果在 ul.space-y-4 > li[itemprop='mainEntity'] > a[itemprop='url']
    for li in soup.select("ul.space-y-4 li[itemprop='mainEntity']"):
        author_el = li.select_one("[itemprop='author']")
        a = li.select_one("a[itemprop='url']")
        if a:
            href = a.get("href")
            title_el = a.select_one("h2[itemprop='name']")
            title = title_el.get_text(strip=True) if title_el else ""
            if title and href:
                books.append({
                    "bookTitle": title,
                    "bookAuthor": author_el.get_text(strip=True) if author_el else "",
                    "bookUrl": urljoin(getSiteUrl(), href),
                })

    return books


def getDetails(url):
    html = _fetch(url)
    soup = BeautifulSoup(html, "html.parser")

    title_el = soup.select_one("h1")
    author_el = soup.select_one("[itemprop='author']")
    intro_el = soup.select_one("meta[property='og:description']")
    cover_el = soup.select_one("meta[property='og:image']")

    book = {
        "url": url,
        "title": title_el.get_text(strip=True) if title_el else "",
        "author": author_el.get_text(strip=True) if author_el else "",
        "intro": intro_el.get("content", "") if intro_el else "",
        "cover": urljoin(url, cover_el.get("content", "")) if cover_el else "",
        "chapterList": []
    }

    # 章节列表在 a.chp-link（排除继续阅读等导航按钮）
    chapter_links = soup.select("a.chp-link")
    seen = set()
    chapters = []
    for a in chapter_links:
        href = a.get("href")
        if not href or href in seen:
            continue
        seen.add(href)
        # get_text 对部分链接失效，统一用 NavigableString 取第一个文本节点
        title = ""
        for desc in a.descendants:
            if isinstance(desc, NavigableString) and desc.strip():
                title = desc.strip()
                break
        if title and title not in ("继续阅读", "开始阅读"):
            chapters.append({
                "title": title,
                "url": urljoin(url, href)
            })

    # 页面顺序非正序，按 href 中的章节 ID 排序
    def _chap_id(c):
        m = re.search(r"/(\d+)\.html", c["url"])
        return int(m.group(1)) if m else 0
    chapters.sort(key=_chap_id)
    book["chapterList"] = chapters

    return book


def getChapterContent(url):
    html = _fetch(url)
    soup = BeautifulSoup(html, "html.parser")

    # 正文在 #article-content（class reader-text）
    con = soup.select_one("#article-content")
    if not con:
        con = soup.select_one(".reader-text")
    if not con:
        con = soup.select_one("article")

    if not con:
        return ""

    # 删除广告容器
    for ad in con.select(".ad-container"):
        ad.decompose()

    return con.prettify()

import html
import json
import re
from urllib.parse import urljoin

import requests
from requests.adapters import HTTPAdapter
from urllib3.util import Retry
from log import log

# 书海阁：https://book.feius.live/
# 书海阁：https://book.washai.net/
# 页面内容全部由前端 AJAX 渲染，因此直接调用站点自身的 JSON 接口：
#   搜索   GET /book/searchByPage?curr=&limit=&keyword=
#   详情   GET /book/queryBookDetail/{bookId}
#   目录   GET /book/queryIndexList?bookId=&curr=&limit=&orderBy=index_num asc
#   正文   GET /book/queryReadPage?bookId=&bookIndexId=

# 1. 初始化全局 Session，实现连接复用与 TCP 握手共享
session = requests.Session()

# 2. 配置底层自动重试（网络波动 / 超时 / 5xx）
retries_strategy = Retry(
    total=3,
    backoff_factor=1,
    status_forcelist=[500, 502, 503, 504],
    raise_on_status=False
)
adapter = HTTPAdapter(max_retries=retries_strategy)
session.mount("http://", adapter)
session.mount("https://", adapter)

# 统一配置全局 headers
session.headers.update({
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/114.0.0.0 Safari/537.36",
    "Accept": "application/json, text/plain, */*",
    "Accept-Language": "zh-CN,zh;q=0.9,en;q=0.8",
    "Referer": "https://book.washai.net/",
})

# 站点接口单页上限（实测 limit 传再大也会被服务端压回 100）
_PAGE_LIMIT = 100
# 目录抓取安全阀，避免接口异常时死循环
_MAX_PAGE = 200

# 上一次成功的请求通道："session"（直连 requests）或 "webview"（WebView 渲染）。
# 下次请求优先复用该通道，避免重复试错，并利用 WebView 已建立的会话与长连接。
_last_channel = None


def getSiteUrl():
    return "https://book.washai.net"


def _request(url, params=None):
    """优先复用上一次成功的通道（利用 WebView 会话与长连接），失败再回退到另一通道"""
    global _last_channel
    channels = [("session", _request_by_session), ("webview", _request_by_webview)]
    if _last_channel:
        channels.sort(key=lambda item: item[0] != _last_channel)

    last_error = None
    for name, handler in channels:
        try:
            result = handler(url, params)
            if _last_channel != name:
                log(f"书海阁请求通道切换为 {name}")
            _last_channel = name
            return result
        except Exception as e:
            last_error = e
            log(f"书海阁 {name} 通道请求失败: {e}")
    raise last_error


def _request_by_session(url, params=None):
    response = session.get(url, params=params, timeout=(10, 30))
    response.encoding = "utf-8"
    return _parse_json(response.text)


def _request_by_webview(url, params=None):
    # 延迟导入：zeroconf / WebView 相关依赖只在降级兜底时才需要
    from urllib.parse import urlencode

    from SessionManager import verification_activity_get
    from WebViewClient import web_get

    full_url = url
    if params:
        full_url = f"{url}?{urlencode(params)}"

    def parse(result):
        result = json.loads(result)
        html_text = result.get("html", "")
        if "https://challenges.cloudflare.com" in html_text:
            raise Exception("人机验证")
        if "此验证用于防止机器人自动化访问" in html_text:
            raise Exception("人机验证")
        return _parse_json(html_text)

    try:
        return parse(web_get(full_url))
    except Exception as e:
        log(f"书海阁 web_get failed: {e}")
        return parse(verification_activity_get(full_url))


def _parse_json(text):
    """从响应文本中提取 JSON（兼容 WebView 返回的 <pre> 包裹内容）"""
    text = (text or "").strip()
    try:
        data = json.loads(text)
    except ValueError:
        start = text.find("{")
        end = text.rfind("}")
        if start < 0 or end <= start:
            raise Exception("响应不是 JSON，可能触发了人机验证")
        # WebView 渲染 JSON 时会做 HTML 转义
        data = json.loads(html.unescape(text[start:end + 1]))

    if not isinstance(data, dict) or data.get("code") != 200:
        raise Exception(f"接口返回异常: {data.get('msg') if isinstance(data, dict) else 'unknown'}")
    return data.get("data") or {}


def _getBookId(url):
    """从 /book/{bookId}.html 或 /book/{bookId}/{indexId}.html 中提取 bookId"""
    m = re.search(r"/book/(\d+)(?:\.html|/)", str(url))
    if not m:
        raise Exception(f"无法从链接中解析书籍 ID: {url}")
    return m.group(1)


def _api(path, params=None):
    return _request(urljoin(getSiteUrl(), path), params)


def _parse_index_items(book_id, items):
    """把 queryIndexList 返回的 list 转成章节字典列表"""
    chapters = []
    for item in items or []:
        index_id = str(item.get("id") or "").strip()
        title = str(item.get("indexName") or "").strip()
        if not index_id or not title:
            continue
        chapters.append({
            "title": title,
            "url": urljoin(getSiteUrl(), f"/book/{book_id}/{index_id}.html"),
        })
    return chapters


def _chapter_index_id(url):
    """提取章节链接中的章节 ID（/book/{bookId}/{indexId}.html）"""
    m = re.search(r"/book/\d+/(\d+)(?:\.html)?", str(url))
    return m.group(1) if m else str(url).strip().rstrip("/")


def _get_all_chapters(book_id):
    """全量抓取目录：每页 100 章，按章节序号正序"""
    chapters = []
    total = 0
    curr = 1
    while curr <= _MAX_PAGE:
        data = _api("/book/queryIndexList", {
            "bookId": book_id,
            "curr": curr,
            "limit": _PAGE_LIMIT,
            "orderBy": "index_num asc",
        })
        total = int(data.get("total") or 0)
        items = data.get("list") or []
        if not items:
            break
        chapters.extend(_parse_index_items(book_id, items))
        if total and len(chapters) >= total:
            break
        curr += 1
    return chapters


def _get_latest_chapters(book_id, last_chapter_url):
    """按分页从后往前加载目录，直到命中本地最新章节所在分页

    从全书最新章节所在分页（index_num desc 第 1 页）开始，按分页从后往前加载，
    直到某页包含本地已缓存的最新章节为止。无论是否有更新，都会返回这段包含
    本地最新章节的分页章节列表（旧->新排序），由调用方与本地已缓存章节拼接去重。
    """
    anchor = _chapter_index_id(last_chapter_url)

    collected = []  # 页内及页间均为 新->旧
    total = 0
    curr = 1
    while curr <= _MAX_PAGE:
        data = _api("/book/queryIndexList", {
            "bookId": book_id,
            "curr": curr,
            "limit": _PAGE_LIMIT,
            "orderBy": "index_num desc",
        })
        total = int(data.get("total") or 0)
        items = data.get("list") or []
        if not items:
            break
        page = _parse_index_items(book_id, items)
        collected.extend(page)
        # 当前分页已包含本地最新章节，说明已回溯到本地进度，无需继续往前加载
        if any(_chapter_index_id(c["url"]) == anchor for c in page):
            break
        if total and curr * _PAGE_LIMIT >= total:
            # 已翻到最后仍未命中本地章节（本地记录可能已失效），返回已抓取部分
            break
        curr += 1

    collected.reverse()  # 转为 旧->新
    return collected


def search(query):
    """搜索书籍，返回 [{bookTitle, bookAuthor, bookUrl}]"""
    data = _api("/book/searchByPage", {
        "curr": 1,
        "limit": _PAGE_LIMIT,
        "keyword": query,
    })

    books = []
    for item in data.get("list") or []:
        book_id = str(item.get("id") or "").strip()
        title = str(item.get("bookName") or "").strip()
        if not book_id or not title:
            continue
        books.append({
            "bookTitle": title,
            "bookAuthor": str(item.get("authorName") or "").strip(),
            "bookUrl": urljoin(getSiteUrl(), f"/book/{book_id}.html"),
        })

    return books


def getDetails(url, lastChapterUrl=None):
    """获取书籍详情 + 目录

    :param lastChapterUrl: 本地已缓存的最新章节链接（可选）。
        传入时执行更新检查：从全书最新章节所在分页开始，按分页从后往前加载，
        直到分页包含本地最新章节。无论是否有更新，都会返回包含本地最新章节的
        分页章节列表（旧->新排序），由调用方与本地已缓存章节拼接去重。
    """
    book_id = _getBookId(url)
    detail = _api(f"/book/queryBookDetail/{book_id}")

    info = {
        "url": urljoin(getSiteUrl(), f"/book/{book_id}.html"),
        "title": str(detail.get("bookName") or "").strip(),
        "author": str(detail.get("authorName") or "").strip(),
        "intro": str(detail.get("bookDesc") or "").strip(),
        "cover": urljoin(getSiteUrl(), str(detail.get("picUrl") or "").strip()),
    }

    if not lastChapterUrl:
        # 首次加载：完整目录
        return {**info, "chapterList": _get_all_chapters(book_id)}

    # 检查更新：从后往前按分页加载，直到分页包含本地最新章节；
    # 即使没有更新，也返回包含本地最新章节的分页章节列表，供本地拼接去重
    return {**info, "chapterList": _get_latest_chapters(book_id, lastChapterUrl)}


def _contentToHtml(content, title=None):
    """正文是纯文本（\\n 分行），统一转成 <p> 结构的 HTML"""
    lines = [line.strip() for line in str(content or "").split("\n")]
    # 正文首行通常是重复的章节名，去掉避免与阅读器自带的标题重复
    if title and lines:
        for i, line in enumerate(lines):
            if not line:
                continue
            if line == str(title).strip():
                lines[i] = ""
            break

    paragraphs = []
    for line in lines:
        if not line:
            continue
        # 纯分隔符行转成 <hr/>
        if set(line) == {"-"}:
            paragraphs.append("<hr/>")
        else:
            paragraphs.append(f"<p>{html.escape(line)}</p>")
    return "\n".join(paragraphs)


def getChapterContent(url):
    """获取章节正文（HTML 格式）"""
    m = re.search(r"/book/(\d+)/(\d+)\.html", str(url))
    if not m:
        raise Exception(f"无法从链接中解析章节 ID: {url}")
    book_id, index_id = m.group(1), m.group(2)

    data = _api("/book/queryReadPage", {
        "bookId": book_id,
        "bookIndexId": index_id,
    })

    # VIP 章节未订阅时正文为空
    if data.get("needBuy"):
        return ""

    index_name = (data.get("bookIndex") or {}).get("indexName")
    return _contentToHtml(data.get("content"), index_name)

import re
from urllib.parse import urljoin

import requests
