        return []

    response = _session.get(
        urljoin(getSiteUrl(), "/s.php") + "?q=" + quote(query),
        timeout=30,
    )
    response.encoding = "utf-8"
    soup = BeautifulSoup(response.text, "html.parser")

    key = _norm(query)
    books = []
    seen = set()
    seen_titles = set()
    for a in soup.select("a[href*='/book/']"):
        href = (a.get("href") or "").strip()
        title = a.get_text(strip=True)
        if not title or not href or "/book/" not in href:
            continue
        if key and key not in _norm(title):
            continue
        book_url = urljoin(getSiteUrl(), href)
        title_key = _norm(title)
        if book_url in seen or title_key in seen_titles:
            continue
        seen.add(book_url)
        seen_titles.add(title_key)
        books.append({
            "bookTitle": title,
            "bookUrl": book_url,
            "bookAuthor": "",
        })

    return books


